import{_ as e,c as l,o as n,a3 as a}from"./chunks/framework.BusRvirq.js";const p=JSON.parse('{"title":"하자보수 및 운영 유지보수 서비스 수준 협약서 (SLA)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/12_SLA_Maintenance_Agreement_template.html"}]]},"headers":[],"relativePath":"public/templates/12_SLA_Maintenance_Agreement_template.md","filePath":"public/templates/12_SLA_Maintenance_Agreement_template.md","lastUpdated":1790810085000}'),r={name:"public/templates/12_SLA_Maintenance_Agreement_template.md"};function i(s,t,o,d,g,c){return n(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="하자보수-및-운영-유지보수-서비스-수준-협약서-sla" tabindex="-1">하자보수 및 운영 유지보수 서비스 수준 협약서 (SLA) <a class="header-anchor" href="#하자보수-및-운영-유지보수-서비스-수준-협약서-sla" aria-label="Permalink to “하자보수 및 운영 유지보수 서비스 수준 협약서 (SLA)”">​</a></h1><p>본 협약서는 [발주회사명] (이하 &quot;고객사&quot;라 한다)과 주식회사 엠파시 (이하 &quot;서비스 제공자&quot;라 한다)가 [프로젝트명]으로 구축된 시스템의 안정적인 운영, 무상 하자담보 책임의 이행 및 유상 운영 유지보수(Maintenance) 서비스의 수준(Service Level Agreement: SLA)을 확립하기 위해 체결한다.</p><hr><h3 id="제1조-목적-및-적용-범위" tabindex="-1">제1조 (목적 및 적용 범위) <a class="header-anchor" href="#제1조-목적-및-적용-범위" aria-label="Permalink to “제1조 (목적 및 적용 범위)”">​</a></h3><ol><li>본 협약은 고객사 시스템의 가용성, 성능, 무결성을 유지하기 위한 기술 지원 및 장애 복구 절차, 서비스 목표 수준을 규정함을 목적으로 한다.</li><li>적용 기간은 최종 검수 완료일 익일부터 개시되는 <strong>1년간의 무상 하자보수 기간</strong> 및 이후 상호 합의에 따라 갱신되는 <strong>유상 운영 유지관리 계약 기간</strong>에 동일하게 적용한다.</li></ol><hr><h3 id="제2조-무상-하자보수와-유상-유지보수의-엄격한-경계" tabindex="-1">제2조 (무상 하자보수와 유상 유지보수의 엄격한 경계) <a class="header-anchor" href="#제2조-무상-하자보수와-유상-유지보수의-엄격한-경계" aria-label="Permalink to “제2조 (무상 하자보수와 유상 유지보수의 엄격한 경계)”">​</a></h3><p>소프트웨어 산업 표준 및 분쟁 방지를 위하여 무상 하자보수의 대상과 유상 과업의 범위를 아래와 같이 명확히 구분한다.</p><ol><li><strong>무상 하자보수 대상 (무상 처리)</strong>: <ul><li>계약상 명시된 과업내용서 및 최종 승인된 설계서(RTM, SRS) 대비 소스코드의 명백한 결함(Bug)이나 오작동</li><li>정상적인 데이터 입력 조건에서 발생하는 데이터 누락, 연산 오류, 예외 에러(Exception)</li><li>계약 범위 내에서 구축된 배치(Batch) 작업 및 인터페이스의 자체 동작 오류</li></ul></li><li><strong>유상 유지보수 및 별도 과업 대상 (무상 대상 제외)</strong>: <ul><li>고객사 내부 규정 개정, 신규 업무 규칙 도입 등으로 인한 비즈니스 로직 변경 및 신규 화면/메뉴 추가</li><li>고객사가 관리하는 타 연계 기관의 API 규격 변경, 통신 프로토콜 변경에 따른 어댑터 재개발</li><li>고객사 측의 운영 미숙, 임의의 소스코드 수정, DB 직접 임의 조작(Manual UPDATE/DELETE)으로 인한 데이터 왜곡 복구</li><li>상용 LLM 모델(OpenAI, Anthropic 등)의 버전 단종(Deprecation)으로 인한 프롬프트 전면 재튜닝</li><li>상용 클라우드 인프라 비용 및 LLM API 토큰 호출 비용(고객사 직접 부담 원칙)</li></ul></li></ol><hr><h3 id="제3조-장애-등급-분류-및-목표-서비스-수준" tabindex="-1">제3조 (장애 등급 분류 및 목표 서비스 수준) <a class="header-anchor" href="#제3조-장애-등급-분류-및-목표-서비스-수준" aria-label="Permalink to “제3조 (장애 등급 분류 및 목표 서비스 수준)”">​</a></h3><p>서비스 제공자는 고객사로부터 장애 접수 시 아래의 목표 응답 및 해결 시간(SLA)을 준수하기 위해 최선의 노력을 다한다.</p><table tabindex="0"><thead><tr><th style="text-align:center;">장애 등급</th><th style="text-align:left;">심각도 정의</th><th style="text-align:center;">최초 응답 시간</th><th style="text-align:center;">임시 조치 (우회)</th><th style="text-align:center;">근본 조치 완료</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>P1 (긴급 / Critical)</strong></td><td style="text-align:left;">전체 시스템 다운, 전사 결제/정산 마비, 핵심 데이터베이스 손상</td><td style="text-align:center;"><strong>30분 이내</strong></td><td style="text-align:center;">2시간 이내</td><td style="text-align:center;">6시간 이내</td></tr><tr><td style="text-align:center;"><strong>P2 (중요 / Major)</strong></td><td style="text-align:left;">주요 업무 기능 마비이나 우회 작업 가능, 대외 연계 일시 지연</td><td style="text-align:center;"><strong>1시간 이내</strong></td><td style="text-align:center;">4시간 이내</td><td style="text-align:center;">12시간 이내</td></tr><tr><td style="text-align:center;"><strong>P3 (보통 / Minor)</strong></td><td style="text-align:left;">특정 보고서 조회 오류, 비핵심 관리자 기능 장애, 단순 배치 지연</td><td style="text-align:center;"><strong>2시간 이내</strong></td><td style="text-align:center;">8시간 이내</td><td style="text-align:center;">24시간 이내</td></tr><tr><td style="text-align:center;"><strong>P4 (경미 / Request)</strong></td><td style="text-align:left;">단순 UI 오탈자, 화면 레이블 변경, 통계 엑셀 출력 서식 미세 조정</td><td style="text-align:center;"><strong>4시간 이내</strong></td><td style="text-align:center;">협의 일정</td><td style="text-align:center;">정기 패치일 반영</td></tr></tbody></table><hr><h3 id="제4조-기술-지원-채널-및-운영-시간" tabindex="-1">제4조 (기술 지원 채널 및 운영 시간) <a class="header-anchor" href="#제4조-기술-지원-채널-및-운영-시간" aria-label="Permalink to “제4조 (기술 지원 채널 및 운영 시간)”">​</a></h3><ol><li><strong>정규 지원 시간</strong>: 평일 09:00 ~ 18:00 (토/일요일, 법정 공휴일 제외)</li><li><strong>긴급 장애(P1) 대응</strong>: 긴급 장애에 한하여 24시간 x 365일 온콜(On-Call) 비상 연락망 가동</li><li><strong>접수 채널</strong>: <ul><li>공식 이슈 관리 시스템 (Jira / 이메일): [ <a href="mailto:maintenance@empasy.com" target="_blank" rel="noreferrer">maintenance@empasy.com</a> ]</li><li>고객 지원 핫라인: [ 02-XXX-XXXX ]</li></ul></li></ol><hr><h3 id="제5조-ai-및-클라우드-인프라-finops-비용-정산-원칙" tabindex="-1">제5조 (AI 및 클라우드 인프라 FinOps 비용 정산 원칙) <a class="header-anchor" href="#제5조-ai-및-클라우드-인프라-finops-비용-정산-원칙" aria-label="Permalink to “제5조 (AI 및 클라우드 인프라 FinOps 비용 정산 원칙)”">​</a></h3><ol><li><strong>토큰 및 컴퓨팅 비용 귀속</strong>: <ul><li>시스템 운영 중 발생하는 외부 LLM API 호출 토큰 비용 및 클라우드 인프라(AWS, GCP, Azure, 네이버클라우드) 비용은 <strong>실비 정산(Pass-through) 원칙</strong>에 따라 고객사가 전액 부담한다.</li></ul></li><li><strong>월간 비용 리포트 제공</strong>: <ul><li>서비스 제공자는 매월 1회 API 호출량 추이, 토큰 소비량, 이상 징후 감지 내역이 포함된 &quot;AI FinOps 월간 운영 보고서&quot;를 고객사에 제공한다.</li></ul></li></ol><hr><h3 id="제6조-유상-계약-전환-시의-요율-기준" tabindex="-1">제6조 (유상 계약 전환 시의 요율 기준) <a class="header-anchor" href="#제6조-유상-계약-전환-시의-요율-기준" aria-label="Permalink to “제6조 (유상 계약 전환 시의 요율 기준)”">​</a></h3><ol><li>무상 하자보수 기간(1년) 만료 후 유상 운영 유지관리 계약을 체결할 경우, 소프트웨어 진흥법 및 한국소프트웨어산업협회(KOSA) 소프트웨어사업 대가산정 가이드에 의거하여 <strong>순수 소프트웨어 개발 구축 금액의 [ 10% ~ 15% ] 범위</strong>에서 연간 계약 금액을 산정한다.</li></ol><hr><p><strong>체결일자: 202 년 월 일</strong></p><p><strong>[고객사]</strong></p><ul><li>회사명: 주식회사 [고객회사명]</li><li>대표이사: [ ] (인)</li></ul><p><strong>[서비스 제공자]</strong></p><ul><li>회사명: 주식회사 엠파시</li><li>대표이사: [ ] (인)</li></ul>',28)])])}const _=e(r,[["render",i]]);export{p as __pageData,_ as default};
